(function(){
    var bookId = String(baseUrl).split('/audiolist-4/')[1];
    if (bookId) bookId = bookId.split('?')[0];
    var cid = String(java.getString('$.cid') || '');

    var cache = {};
    try { cache = JSON.parse(source.getVariable()); } catch(e) {}

    var devId = cache.dev_id || '';
    if (!devId) {
        devId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c){
            var r = Math.random()*16|0, v = c=='x'?r:(r&0x3|0x8);
            return v.toString(16);
        });
        cache.dev_id = devId;
    }

    var shuKey = 'shu_' + bookId;
    var dirKey = 'dir_' + bookId;
    var shuId = cache[shuKey] || '';
    var dirHcCode = cache[dirKey] || '';

    // 从目录接口拿 shuId + dirHcCode（一次性，缓存复用）
    if (!shuId || !dirHcCode) {
        try {
            var r = java.ajax('https://ts3.txs12.com/audiolist-4/' + bookId + '?https=1&dirHcCode=');
            var j = JSON.parse(String(r));
            if (j.data) {
                if (!shuId && j.data.chapterUrl) {
                    var m = String(j.data.chapterUrl).match(/shuId=(\d+)/);
                    if (m) shuId = m[1];
                }
                if (!dirHcCode) dirHcCode = String(j.data.dirHcCode || '');
                if (shuId) cache[shuKey] = shuId;
                if (dirHcCode) cache[dirKey] = dirHcCode;
            }
        } catch(e) {}
        if (!shuId) {
            try {
                var r2 = java.ajax('https://ts3.txs12.com/bookinfo/' + bookId + '?language=zh_cn');
                var j2 = JSON.parse(String(r2));
                if (j2.data && j2.data.x_id) {
                    shuId = String(j2.data.x_id);
                    cache[shuKey] = shuId;
                }
            } catch(e2) {}
        }
    }
    source.setVariable(JSON.stringify(cache));

    var ts = new Date().getTime();
    var tt = String(Math.floor(ts / 1000));
    var computed = Math.floor(ts / 10000) + 5;

    // token = md5('?' + shuId&_id&dirHcCode&cid（p1原始query顺序） + computed + 'cV2')
    var token = String(java.md5Encode('?shuId=' + shuId + '&_id=' + bookId + '&dirHcCode=' + dirHcCode + '&cid=' + cid + computed + 'cV2'));

    // 10参数：URL与签名均按 TreeMap(key) 排序
    var allParams = {
        '_id': bookId,
        'app_name': APP_NAME,
        'app_vc': APP_VC,
        'app_vn': APP_VER,
        'cid': cid,
        'dev_id': devId,
        'dirHcCode': dirHcCode,
        'shuId': shuId,
        'token': token,
        'ts': String(ts)
    };
    var sortedKeys = Object.keys(allParams).sort();
    var urlParts = [];
    var signParts = [];
    for (var i = 0; i < sortedKeys.length; i++) {
        var k = sortedKeys[i];
        var v = allParams[k];
        urlParts.push(k + '=' + encodeURIComponent(v));
        signParts.push(k + '=' + v);
    }
    var urlStr = urlParts.join('&');
    var signStr = signParts.join('&');

    // ss = nativeSign(md5(basePath + 排序参数 + tt + '+' + SECRET).toUpperCase())
    var signSource = 'https://res.txs12.com/cV2/' + signStr + tt + '+' + ESFEJJ_SECRET;
    var md5Result = String(java.md5Encode(signSource));
    var ss = nativeSign(md5Result.toUpperCase());

    var finalUrl = 'https://res.txs12.com/cV2/?' + urlStr;
    var opt = {'headers': {'ss': ss, 'tt': tt}};
    return finalUrl + ',' + JSON.stringify(opt);
})()

